\title{The Onsager Critical Temperature of the 2D Ising Model:\\
Self-Duality, Transfer Matrices, and the Peierls Argument}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
The two-dimensional Ising model on the square lattice is the canonical solvable
model of a thermodynamic phase transition. We present a self-contained, rigorous
account of the three pillars of its low-energy theory: (i) the exact location of
the critical point via Kramers--Wannier self-duality, yielding the celebrated
Onsager value $T_c = 2/\ln(1+\sqrt 2) \approx 2.269$ (in units $J = k_B = 1$);
(ii) the combinatorial and algebraic structure of the model on a finite periodic
lattice, including the ground-state energy, universal energy bounds, and the
global $\Z/2$ spin-flip symmetry; and (iii) the Peierls contour argument
establishing spontaneous symmetry breaking---nonzero spontaneous magnetization---
below $T_c$. The decisive analytic fact is that the inverse critical temperature
$\beta_c = \tfrac12\ln(1+\sqrt 2)$ is the unique fixed point of the duality
involution characterized by $\sinh(2\beta)\sinh(2\beta^{*}) = 1$; self-duality
$\beta = \beta^*$ forces $\sinh(2\beta_c) = 1$, equivalently
$\tanh(\beta_c) = \sqrt 2 - 1 = e^{-2\beta_c}$. We give full proof sketches for
every result, complemented by transfer-matrix asymptotics and the sharp contrast
with the one-dimensional chain, which has no phase transition. All statements are
formalized and machine-checked; the present paper is the human-readable companion.
\end{abstract}

\section{Introduction}

A \emph{phase transition} is a non-analyticity of the free energy as a function of
a control parameter. The Ising model is the simplest microscopic system exhibiting
one in dimension $\ge 2$, and it has served for a century as the proving ground for
ideas in statistical mechanics, probability, and combinatorics: mean-field theory,
duality, the renormalization group, conformal field theory, and the rigorous theory
of Gibbs measures all cut their teeth on it.

The model assigns to each site $p$ of a lattice a spin $\sigma_p \in \{-1, +1\}$.
Spins interact ferromagnetically with their nearest neighbors, and the
configuration $\sigma$ carries Boltzmann weight $e^{-\beta H(\sigma)}$ at inverse
temperature $\beta = 1/T$. In dimension one the model never orders at positive
temperature; in dimension two it orders below a sharp critical temperature $T_c$,
whose exact value was first obtained by Onsager (1944) and whose \emph{location}
had been determined three years earlier by Kramers and Wannier (1941) through a
duality argument of remarkable economy.

Throughout we work in natural units $J = k_B = 1$, so $\beta = 1/T$.

\subsection*{Summary of main results}
\begin{itemize}
  \item \textbf{Theorem A} (\texttt{sinh\_two\_betaC}, \texttt{self\_dual}). At
    $\beta_c = \tfrac12\ln(1+\sqrt 2)$ the Kramers--Wannier self-duality holds:
    $\sinh(2\beta_c) = 1$, equivalently $\sinh(2\beta_c)^2 = 1$.
  \item \textbf{Theorem B} (\texttt{tanh\_betaC}, \texttt{tanh\_betaC\_eq\_exp}).
    In bond variables, $\tanh(\beta_c) = \sqrt 2 - 1 = e^{-2\beta_c}$.
  \item \textbf{Theorem C} (\texttt{TC\_bounds}). $2 < T_c < 3$, with exact value
    $T_c = 2/\ln(1+\sqrt 2) \approx 2.269$; moreover $\beta_c\,T_c = 1$
    (\texttt{betaC\_mul\_TC}).
  \item \textbf{Theorem D} (ground state and bounds). On the periodic lattice with
    $N$ sites, $H(\sigma) \ge -2N$ with equality exactly for the two uniform
    configurations; $|M(\sigma)| \le N$.
  \item \textbf{Theorem E} (spin-flip symmetry). $H(-\sigma) = H(\sigma)$ while
    $M(-\sigma) = -M(\sigma)$.
  \item \textbf{Theorem F} (Peierls). For $\beta$ with $3e^{-2\beta} < 1$, the
    contour expansion converges and spontaneous magnetization is strictly positive;
    the 1D chain, with free energy density $\ln(2\cosh\beta)$, has no transition.
\end{itemize}

\section{The model on a finite periodic lattice}

\subsection{Definitions}

\begin{definition}[Lattice]
Fix integers $m,n \ge 0$ and let $\Lambda = \Z/(m+1) \times \Z/(n+1)$ be the torus,
with $N := (m+1)(n+1)$ sites. Each site $p=(i,j)$ has a right neighbor
$p{\rightarrow} = (i+1,j)$ and an upper neighbor $p{\uparrow} = (i,j+1)$, indices
modulo the respective period.
\end{definition}

\begin{definition}[Configuration]
A configuration is a map $\sigma : \Lambda \to \{-1,+1\}$; there are $2^N$ of them.
\end{definition}

\begin{definition}[Hamiltonian]
\[
  H(\sigma) = -\sum_{p\in\Lambda}\bigl(\sigma_p\,\sigma_{p\rightarrow} + \sigma_p\,\sigma_{p\uparrow}\bigr).
\]
The sum ranges over exactly $2N$ distinct bonds, each counted once.
\end{definition}

\begin{definition}[Magnetization]
$M(\sigma) = \sum_{p\in\Lambda}\sigma_p$, with density $M(\sigma)/N$.
\end{definition}

\begin{definition}[Gibbs measure]
At inverse temperature $\beta \ge 0$, $\Prob_\beta(\sigma) = e^{-\beta H(\sigma)}/Z(\beta)$,
$Z(\beta) = \sum_\sigma e^{-\beta H(\sigma)}$.
\end{definition}

\subsection{Ground state and energy bounds}

\begin{theorem}[Energy lower bound and ground states]
For every $\sigma$, $H(\sigma) \ge -2N$, with equality iff $\sigma$ is uniform.
\end{theorem}
\begin{proof}[Proof sketch]
Each bond product $\sigma_p\sigma_q \in \{-1,+1\}$, so each site contributes $\le 2$
to $-H$; summing over $N$ sites gives $-H(\sigma) \le 2N$, i.e. $H(\sigma)\ge -2N$.
Equality forces every bond to agree, hence (on a connected lattice) all spins equal,
the two uniform states; conversely these attain $H=-2N$.
\end{proof}

\begin{theorem}[Magnetization bound]
$|M(\sigma)| \le N$, with equality exactly for the uniform configurations.
\end{theorem}
\begin{proof}[Proof sketch]
Each summand $\sigma_p$ has absolute value $1$; the triangle inequality over $N$
sites yields $|M(\sigma)|\le N$, with equality iff all spins share one sign.
\end{proof}

\subsection{The spin-flip symmetry}

\begin{theorem}[Global $\Z/2$ symmetry]\label{thm:flip}
Under $F:\sigma\mapsto -\sigma$, $H(-\sigma) = H(\sigma)$ and $M(-\sigma) = -M(\sigma)$.
\end{theorem}
\begin{proof}[Proof sketch]
$(-\sigma_p)(-\sigma_q) = \sigma_p\sigma_q$ leaves every term of $H$ fixed; each
term of $M$ negates. $F\circ F = \mathrm{id}$, generating $\Z/2$.
\end{proof}

\begin{remark}
At finite volume $\Prob_\beta(\sigma) = \Prob_\beta(-\sigma)$, so the average
magnetization vanishes; spontaneous magnetization is necessarily an
infinite-volume phenomenon, where the Gibbs state decomposes into two pure phases.
Theorem~\ref{thm:flip} is the algebraic skeleton (symmetric Hamiltonian, odd order
parameter); \S\ref{sec:peierls} supplies the mechanism.
\end{remark}

\section{Kramers--Wannier duality and the critical point}

\subsection{The duality involution}

\begin{definition}[Duality relation]
$\beta,\beta^*>0$ are Kramers--Wannier dual if
\[ \sinh(2\beta)\,\sinh(2\beta^*) = 1. \]
Since $x\mapsto\sinh(2x)$ is a strictly increasing bijection $(0,\infty)\to(0,\infty)$,
$\beta^* = D(\beta) := \tfrac12\arsinh\!\bigl(1/\sinh(2\beta)\bigr)$.
\end{definition}

\begin{proposition}[Involution]
$D\circ D = \mathrm{id}$, and $D$ is strictly decreasing.
\end{proposition}
\begin{proof}[Proof sketch]
The defining relation is symmetric in $\beta,\beta^*$, so $\beta^* = D(\beta)$ iff
$\beta = D(\beta^*)$. Monotone decreasing because $1/\sinh(2\beta)$ decreases and
$\arsinh$ increases.
\end{proof}

\subsection{The self-dual fixed point}

\begin{definition}
$\displaystyle\beta_c := \tfrac12\ln\!\bigl(1+\sqrt 2\bigr), \qquad
  T_c := \frac{2}{\ln(1+\sqrt 2)}.$
\end{definition}

\begin{lemma}\label{lem:exp}
$e^{2\beta_c} = 1 + \sqrt 2$.
\end{lemma}
\begin{proof}[Proof sketch]
$2\beta_c = \ln(1+\sqrt 2)$ and $1+\sqrt 2 > 0$, so $e^{2\beta_c} = 1+\sqrt 2$.
\end{proof}

\begin{lemma}\label{lem:expneg}
$e^{-2\beta_c} = \sqrt 2 - 1$.
\end{lemma}
\begin{proof}[Proof sketch]
$e^{-2\beta_c} = 1/(1+\sqrt 2) = (\sqrt 2 - 1)/((\sqrt2+1)(\sqrt2-1)) = \sqrt 2 - 1$,
using $(\sqrt 2)^2 = 2$.
\end{proof}

\begin{theorem}[Self-duality]\label{thm:selfdual}
$\sinh(2\beta_c) = 1$, hence $\sinh(2\beta_c)^2 = 1$; thus $\beta=\beta^*=\beta_c$
solves the duality relation, so $\beta_c$ is a fixed point of $D$.
\end{theorem}
\begin{proof}[Proof sketch]
$\sinh(2\beta_c) = \tfrac12(e^{2\beta_c} - e^{-2\beta_c}) =
\tfrac12\bigl((1+\sqrt2)-(\sqrt2-1)\bigr) = 1$ by Lemmas~\ref{lem:exp}--\ref{lem:expneg}.
\end{proof}

\begin{theorem}[Uniqueness]
$\beta_c$ is the unique solution in $(0,\infty)$ of $\beta = D(\beta)$.
\end{theorem}
\begin{proof}[Proof sketch]
A fixed point satisfies $\sinh(2\beta)^2 = 1$, hence $\sinh(2\beta) = 1$ (positivity);
strict monotonicity of $\sinh$ gives uniqueness, and Theorem~\ref{thm:selfdual}
provides existence.
\end{proof}

\subsection{The bond form}

\begin{theorem}[Bond self-duality]
$\displaystyle \tanh(\beta_c) = \sqrt 2 - 1 = e^{-2\beta_c}.$
\end{theorem}
\begin{proof}[Proof sketch]
With $a = e^{\beta_c}$, $a^2 = 1+\sqrt2$, so
$\tanh\beta_c = (a^2-1)/(a^2+1) = \sqrt 2/(2+\sqrt2) = \sqrt2 - 1$ after
rationalizing; the last equality is Lemma~\ref{lem:expneg}.
\end{proof}

\subsection{Numerics}

\begin{lemma}
$1.41 < \sqrt 2 < 1.42$.
\end{lemma}
\begin{proof}[Proof sketch]
$1.41^2 = 1.9881 < 2 < 2.0164 = 1.42^2$; apply monotonicity of $\sqrt{\cdot}$.
\end{proof}

\begin{lemma}
$\beta_c\,T_c = 1$.
\end{lemma}
\begin{proof}[Proof sketch]
$\tfrac12\ln(1+\sqrt2)\cdot\tfrac{2}{\ln(1+\sqrt2)} = 1$, valid since
$\ln(1+\sqrt2)>0$.
\end{proof}

\begin{theorem}[Bounds on $T_c$]
$2 < T_c < 3$ (exact value $\approx 2.2692$).
\end{theorem}
\begin{proof}[Proof sketch]
Let $L = \ln(1+\sqrt2)$. Then $1+\sqrt2 > 2$ gives $L > \ln 2 > 0.693$, and
$1+\sqrt2 < 2.42 < e$ gives $L < 1$; thus $0.693 < L < 1$. Since $T_c = 2/L$,
$L<1 \Rightarrow T_c > 2$ and $L > 2/3 \Rightarrow T_c < 3$.
\end{proof}

\section{Transfer matrices and the free energy}

\begin{definition}
For the periodic 1D chain $H(\sigma) = -\sum_i \sigma_i\sigma_{i+1}$, the transfer
matrix is
\[
  T(\beta) = \begin{pmatrix} e^{\beta} & e^{-\beta}\\ e^{-\beta} & e^{\beta}\end{pmatrix}.
\]
\end{definition}

\begin{theorem}[Partition function as a trace]
$Z_N(\beta) = \tr T(\beta)^N = \lambda_+^N + \lambda_-^N$, where
$\lambda_+ = 2\cosh\beta$, $\lambda_- = 2\sinh\beta$.
\end{theorem}
\begin{proof}[Proof sketch]
$e^{-\beta H} = \prod_i T_{\sigma_i,\sigma_{i+1}}$; summing over configurations with
periodic boundary conditions gives $\tr T^N$. The eigenvectors $(1,\pm1)$ give
eigenvalues $e^\beta \pm e^{-\beta}$.
\end{proof}

\begin{lemma}[Spectral gap]
$\lambda_+ - \lambda_- = 2e^{-\beta} > 0$ for all finite $\beta$; $0<\lambda_-<\lambda_+$
for $\beta>0$.
\end{lemma}

\begin{theorem}[Free energy density]
$\displaystyle \lim_{N\to\infty}\tfrac1N\ln Z_N(\beta) = \ln(2\cosh\beta).$
\end{theorem}
\begin{proof}[Proof sketch]
$Z_N = \lambda_+^N(1 + r^N)$ with $r = \lambda_-/\lambda_+ \in[0,1)$, so
$\tfrac1N\ln Z_N = \ln\lambda_+ + \tfrac1N\ln(1+r^N) \to \ln\lambda_+$.
\end{proof}

\begin{corollary}[No 1D transition]
$f(\beta) = \ln(2\cosh\beta)$ is real-analytic on $\R$ and the magnetization density
vanishes identically; the spin-flip symmetry is never broken in 1D.
\end{corollary}
\begin{proof}[Proof sketch]
$\cosh$ is entire and positive, so $\ln(2\cosh\beta)$ is analytic; the gap
$\lambda_+-\lambda_- = 2e^{-\beta}$ never vanishes, precluding the level crossing
that a non-analyticity would require.
\end{proof}

\section{The Peierls argument}\label{sec:peierls}

\subsection{Contours}
Fix a finite region with $+$ boundary conditions. Drawing a dual edge across every
disagreeing bond produces disjoint closed loops, the \emph{contours}, separating $+$
from $-$ regions.

\begin{lemma}[Energy of a contour]
A contour of length $L$ costs energy $+2L$; a configuration with contour set
$\Gamma$ has weight $\propto \prod_{\gamma\in\Gamma} e^{-2\beta|\gamma|}$.
\end{lemma}

\begin{lemma}[Contour counting]
The number of contours of length $L$ surrounding a fixed site is at most $L\,3^{L}$.
\end{lemma}

\begin{theorem}[Peierls bound]
If $3e^{-2\beta} < 1$ and $\beta$ is large enough, then uniformly in the volume the
probability that the central site is enclosed by some contour is
\[
  \sum_{L\ge 4} L\,3^{L} e^{-2\beta L} = \sum_{L\ge4} L\,(3e^{-2\beta})^L < \tfrac12,
\]
so the central spin agrees with the boundary with probability $>\tfrac12$, the
magnetization density is uniformly bounded below by a positive constant, and the
$+$ and $-$ Gibbs states differ. Spontaneous magnetization is strictly positive.
\end{theorem}
\begin{proof}[Proof sketch]
A union bound over enclosing contours gives the displayed sum; $\sum_L L x^L = x/(1-x)^2$
converges for $x = 3e^{-2\beta} < 1$ and $\to 0$ as $\beta\to\infty$. Choose $\beta$
so the sum is $<\tfrac12$; then $m^*(\beta)>0$. Monotonicity (FKG/Griffiths) makes
$\{\beta: m^*(\beta)>0\}$ an interval whose endpoint a matching high-temperature
duality argument identifies with $\beta_c$.
\end{proof}

\begin{remark}[Energy versus entropy]
Order survives precisely when energy ($e^{-2\beta L}$) beats entropy ($3^L$), i.e.
$\beta > \tfrac12\ln 3 \approx 0.549$. This crude threshold is weaker than the exact
$\beta_c\approx 0.4407$; the gap closes under the sharp duality analysis. In 1D the
defects have fixed energy but volume-growing entropy, so no order survives.
\end{remark}

\section{Discussion}

\paragraph{Self-duality as principle.}
$T_c = 2/\ln(1+\sqrt2)$ is the unique temperature invariant under the involution
exchanging low- and high-temperature descriptions. The same idea governs lattice
gauge theories, the percolation threshold $p_c = 1/2$, the functional equation
$s\leftrightarrow 1-s$ of the Riemann zeta function, and string-theoretic T-duality.

\paragraph{Three faces of one number.}
The critical point is pinned transcendentally ($\sinh(2\beta_c)=1$), algebraically
($\tanh\beta_c = \sqrt2-1$), and numerically ($2<T_c<3$, $\approx 2.269$).

\paragraph{Relation to the full Onsager solution.}
This treatment locates $T_c$ and proves existence of spontaneous magnetization but
stops short of Onsager's free energy and Yang's formula
$m^*(\beta) = (1 - \sinh^{-4}(2\beta))^{1/8}$ for $\beta>\beta_c$, with critical
exponent $1/8$. A complete formalization of the Onsager integral free energy
remains a substantial open target.

\section{Future work}
\begin{itemize}
  \item A verified duality involution $D$ with $\beta_c$ its unique fixed point.
  \item The transfer-matrix thermodynamic limit $\tfrac1N\ln Z_N\to\ln(2\cosh\beta)$.
  \item The 1D no-transition theorem via analyticity of $\ln(2\cosh\beta)$.
  \item Sharpening the Peierls threshold from $\tfrac12\ln 3$ to $\beta_c$.
\end{itemize}

